import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,_ as c,b as l,k as u,l as d,n as f,o as p,t as m,v as h}from"./shared-CsAEn-Fy.js";import{t as g}from"./CodeEditor-BZlrvoTL.js";var _=e();function v({module:e}){return(0,_.jsxs)(a,{children:[(0,_.jsx)(i,{chip:e??`Блок 4 · Собираем свой Planner`,title:`19.1. Считаем статистику задач`,intro:`Посчитаем текущее состояние Planner и заменим заглушку команды stats реальной сводкой.`,variant:`project`}),(0,_.jsxs)(s,{number:`00`,title:`От списка задач к общей картине`,children:[(0,_.jsx)(o,{children:`Мы уже умеем добавлять задачу, находить её и отмечать выполненной. Теперь посмотрим на список целиком. Одной карточки достаточно, чтобы узнать её статус, но по всему Planner нужны согласованные числа.`}),(0,_.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`После занятия 19 работают add, list, find, done и search. Команда stats уже показана и принимается меню, но пока отвечает заглушкой; у каждой задачи есть поле is_done.`},{title:`Новый вопрос`,description:`Как узнать, сколько задач сейчас всего, сколько завершено и какую долю они составляют, даже если список пуст?`},{title:`Результат`,description:`Команда stats показывает total, completed, left и процент по текущему списку, не меняя сами задачи.`}]}),(0,_.jsx)(`p`,{children:`Сначала отделим состояние карточек от действий, которые к нему привели. Затем разберём один проход по списку, отдельно посчитаем процент и только после этого заменим заглушку уже доступной команды stats. Меню, допустимые команды и прежние операции Planner сохраняются.`})]}),(0,_.jsxs)(s,{number:`01`,title:`Карточка хранит состояние, команда создаёт событие`,children:[(0,_.jsxs)(`p`,{children:[`Поле `,(0,_.jsx)(`code`,{children:`is_done`}),` отвечает на вопрос о карточке сейчас: значение `,(0,_.jsx)(`code`,{children:`True`}),` означает, что задача выполнена, а `,(0,_.jsx)(`code`,{children:`False`}),` означает, что она ещё открыта. Команда `,(0,_.jsx)(`code`,{children:`done`}),` описывает действие пользователя. Эти ответы связаны, но это не одно и то же.`]}),(0,_.jsxs)(`p`,{children:[`Представим список отметок на бумажном контрольном листе. Галочка показывает состояние строки. Число нажатий на ручку не показывает, сколько строк отмечено: можно дважды обвести одну галочку, но строка всё равно одна. Так же повторный `,(0,_.jsx)(`code`,{children:`done`}),` для уже выполненной задачи не создаёт ещё одну задачу и не делает её «выполненной дважды».`]}),(0,_.jsxs)(`p`,{children:[`Поэтому статистика не должна вспоминать историю команд. Она читает текущее `,(0,_.jsx)(`code`,{children:`is_done`}),` у каждой записи. Если два разных запуска привели к одинаковым карточкам, повторный подсчёт даст одинаковый результат, даже если в одном запуске команду `,(0,_.jsx)(`code`,{children:`done`}),` вводили чаще.`]}),(0,_.jsx)(l,{question:`Две задачи имеют одинаковые значения is_done после разных историй команд. Что верно для completed?`,options:[`Счётчик зависит от числа вводов команды done`,`В обоих случаях считаются карточки с is_done == True`,`После первого done completed навсегда равен 1`],correctIndex:1,explanation:`Мы пересчитываем текущее поле каждой задачи, поэтому одинаковое состояние списка даёт одинаковый completed.`}),(0,_.jsxs)(r,{tone:`info`,children:[(0,_.jsx)(`code`,{children:`done`}),` меняет состояние одной найденной записи. `,(0,_.jsx)(`code`,{children:`stats`}),` читает состояния всех записей. Счётчик команд для этой задачи не нужен.`]})]}),(0,_.jsxs)(s,{number:`02`,title:`Счётчики согласуются за один проход`,children:[(0,_.jsxs)(`p`,{children:[`Нам нужны три числа. `,(0,_.jsx)(`code`,{children:`total`}),` означает число всех карточек, `,(0,_.jsx)(`code`,{children:`completed`}),` означает число карточек с истинным `,(0,_.jsx)(`code`,{children:`is_done`}),`, а `,(0,_.jsx)(`code`,{children:`left`}),` означает число незавершённых карточек. Эти значения должны совпадать с тем, что мы увидим в полном списке, а не только с тем, что показала последняя команда.`]}),(0,_.jsxs)(`p`,{children:[`Каждый элемент мы встречаем один раз. Перед циклом начинаем общий счёт с нуля. Для каждой записи добавляем единицу к `,(0,_.jsx)(`code`,{children:`total`}),`; если поле истинно, добавляем единицу и к `,(0,_.jsx)(`code`,{children:`completed`}),`. После цикла незавершённое число получается вычитанием: `,(0,_.jsx)(`code`,{children:`left = total - completed`}),`. Так мы не заводим третий условный счётчик для того, что уже следует из первых двух.`]}),(0,_.jsxs)(`p`,{children:[`Счётчик похож на сумму в кассовом чеке: каждый новый товар добавляет одну позицию, а не стирает число предыдущих товаров. Поэтому строка `,(0,_.jsx)(`code`,{children:`completed += 1`}),` сохраняет уже набранное и увеличивает его на единицу. Присваивание `,(0,_.jsx)(`code`,{children:`completed = 1`}),` каждый раз заменило бы прежний итог, и список с несколькими выполненными карточками ошибочно дал бы только единицу.`]}),(0,_.jsx)(`p`,{children:`Проследим две проверки отправки. Этот список не относится к Planner, но показывает тот же цикл: сначала обнуляем счётчики, затем отдельно увеличиваем общий счёт, проверяем статус и только при True увеличиваем число отправленных. Остаток считаем после выхода из цикла.`}),(0,_.jsx)(h,{code:`checks = [{"sent": True}, {"sent": False}]
total = 0
sent_count = 0
for check in checks:
    total += 1
    if check["sent"]:
        sent_count += 1
left = total - sent_count`,steps:[{line:2,note:`До цикла оба счётчика равны нулю: ни одна проверка ещё не обработана.`,vars:{total:`0`,sent_count:`0`}},{line:4,note:`Первая запись имеет sent=True. Сначала общий счётчик становится равен 1, выполненный пока остаётся 0.`,vars:{total:`1`,sent_count:`0`,check:`{"sent": True}`}},{line:5,note:`Проверяем статус первой записи: условие истинно, поэтому Python перейдёт к телу if.`,vars:{total:`1`,sent_count:`0`,check:`{"sent": True}`}},{line:6,note:`Только после True увеличиваем sent_count. Теперь из одной проверки отправлена одна.`,vars:{total:`1`,sent_count:`1`,check:`{"sent": True}`}},{line:4,note:`Во второй записи sent=False. При входе в тело цикла total становится равен 2, sent_count пока равен 1.`,vars:{total:`2`,sent_count:`1`,check:`{"sent": False}`}},{line:5,note:`Проверка второй записи ложна, поэтому строка sent_count += 1 будет пропущена.`,vars:{total:`2`,sent_count:`1`,check:`{"sent": False}`}},{line:7,note:`Цикл завершён. После его выхода считаем остаток: left = 2 - 1 = 1.`,vars:{total:`2`,sent_count:`1`,left:`1`}}]}),(0,_.jsxs)(`p`,{children:[`Для любого списка после подсчёта должно выполняться равенство `,(0,_.jsx)(`code`,{children:`total = completed + left`}),`. Это проверка согласованности, а не дополнительная операция в цикле. На пустом списке все три числа равны нулю: ни одна карточка не обработана, ни одна не завершена и ни одна не ожидает.`]}),(0,_.jsxs)(`p`,{children:[`На каждом шаге значение счётчика описывает уже обработанную часть списка. До первой записи `,(0,_.jsx)(`code`,{children:`total`}),`равно нулю. После первой записи оно равно единице, после второй двум и так далее. Условный`,(0,_.jsx)(`code`,{children:`completed`}),` растёт только там, где поле текущей задачи истинно. Поэтому по завершении цикла`,(0,_.jsx)(`code`,{children:`total`}),` совпадает с длиной исходного списка, а `,(0,_.jsx)(`code`,{children:`completed`}),` не может быть больше`,(0,_.jsx)(`code`,{children:`total`}),`. Эти границы помогают заметить, если счётчик обновили не в той ветви или сбросили внутри цикла.`]}),(0,_.jsx)(`p`,{children:`Если подсчёт в функции собран правильно, повторный вызов начинает новые локальные счётчики с нуля и читает переданный список заново. Он не помнит предыдущий ответ. После добавления или завершения задачи новый вызов увидит изменённый список, потому что изменилось его состояние.`})]}),(0,_.jsxs)(s,{number:`03`,title:`Функция возвращает сводку, а не печатает её`,children:[(0,_.jsxs)(`p`,{children:[`Функция `,(0,_.jsx)(`code`,{children:`build_statistics(tasks)`}),` получает список Planner и возвращает словарь с тремя согласованными числами. Словарь удобен как один результат: вместо нескольких несвязанных ответов дальше передаётся одна сводка с ключами `,(0,_.jsx)(`code`,{children:`total`}),`, `,(0,_.jsx)(`code`,{children:`completed`}),` и `,(0,_.jsx)(`code`,{children:`left`}),`.`]}),(0,_.jsx)(`p`,{children:`Это похоже на заполненную квитанцию, которую кассир передаёт следующему сотруднику. Внутри расчёта мы заполняем поля, но не объявляем их вслух. Получатель сам решает, как показать значения. Для нашей программы получателем станет ветвь меню, которая напечатает понятные подписи.`}),(0,_.jsxs)(`p`,{children:[`Здесь важно различать `,(0,_.jsx)(`code`,{children:`return`}),` и `,(0,_.jsx)(`code`,{children:`print`}),`. Возврат передаёт значение к месту вызова; печать отправляет текст в окно программы. Если функция только напечатает итог, следующей функции будет нечего прочитать. Если она вернёт словарь, его поля можно использовать для дальнейшего вычисления и вывода.`]}),(0,_.jsx)(t,{rows:[[`return statistics`,`Передаёт словарь вызывающему коду, где можно прочитать его ключи.`],[`print(statistics)`,`Показывает словарь человеку, но сам по себе не передаёт его другой функции.`],[`local counters`,`Создаются при каждом вызове и описывают только переданный список.`]]}),(0,_.jsxs)(`p`,{children:[(0,_.jsx)(`code`,{children:`build_statistics`}),` не печатает и не меняет карточки. Это разделение помогает использовать одну функцию и для пустого списка, и после нескольких изменений, сохраняя данные в одном месте: внутри существующего `,(0,_.jsx)(`code`,{children:`tasks`}),`. Мы не добавляем постоянное хранилище статистики и не создаём отдельный обработчик только ради подсчёта.`]}),(0,_.jsxs)(`p`,{children:[`Результирующий словарь создаётся после того, как известны все три числа. Его ключи являются подписями значения: по ключу `,(0,_.jsx)(`code`,{children:`"completed"`}),` вызывающий код получает количество завершённых задач, а не текст для пользователя. Если изменить имя ключа только при возврате, а в другой функции оставить прежнее, обращение к отсутствующему ключу завершится ошибкой. Поэтому функция и её потребитель согласуют один словарь и одинаковые точные ключи.`]}),(0,_.jsxs)(`p`,{children:[`При вызове Python выполняет тело функции и доходит до `,(0,_.jsx)(`code`,{children:`return`}),`. Возвращённый словарь сохраняется в переменную вызывающего кода. Локальные имена `,(0,_.jsx)(`code`,{children:`total`}),` и `,(0,_.jsx)(`code`,{children:`completed`}),` после вызова больше не нужны самому меню, но их значения уже упакованы в результат. Это позволяет не раскрывать внутренние шаги подсчёта и не превращать счётчики в общие изменяемые переменные.`]}),(0,_.jsxs)(`p`,{children:[`Ранее мы считали минуты отдельной функцией `,(0,_.jsx)(`code`,{children:`calculate_study_minutes(durations)`}),`. Она складывает длительности обучения и остаётся самостоятельной. Сводка задач отвечает на другой вопрос: она читает количество карточек и их статусы. Мы не превращаем старую функцию в команду `,(0,_.jsx)(`code`,{children:`calc`}),` и не заменяем ею работу Planner.`]})]}),(0,_.jsxs)(s,{number:`04`,title:`Доля становится процентом`,children:[(0,_.jsxs)(`p`,{children:[`Процент отвечает на вопрос: какую часть составляет выбранное количество от общего? Сначала мы сравниваем часть с целым и получаем долю. Затем выражаем эту долю на шкале из ста. В статистике задач часть равна`,(0,_.jsx)(`code`,{children:`completed`}),`, а целое равно `,(0,_.jsx)(`code`,{children:`total`}),`.`]}),(0,_.jsx)(`p`,{children:`Представим лист из ста клеток. Если закрашена одна из четырёх равных клеток, это четверть листа. Чтобы представить ту же долю в клетках из ста, мы умножаем четверть на сто и получаем двадцать пять процентов. В этой аналогии одна выполненная карточка играет роль закрашенной части, а все карточки вместе играют роль целого листа. Но задача не становится картинкой: в программе долю дают числовые значения счётчиков.`}),(0,_.jsxs)(`p`,{children:[`В Python оператор `,(0,_.jsx)(`code`,{children:`/`}),` выполняет дробное деление. Поэтому для одной выполненной проверки из трёх сначала получается примерно `,(0,_.jsx)(`code`,{children:`0.3333`}),`, а умножение на сто переводит её в процент, примерно`,(0,_.jsx)(`code`,{children:`33.3333`}),`. Мы округляем уже итоговый процент до одного знака: `,(0,_.jsx)(`code`,{children:`33.3`}),`. Если сначала округлить долю до `,(0,_.jsx)(`code`,{children:`0.3`}),`, после умножения получится `,(0,_.jsx)(`code`,{children:`30.0`}),`, что заметно искажает ответ.`]}),(0,_.jsxs)(`p`,{children:[`Есть два равноценных порядка при ненулевом целом: `,(0,_.jsx)(`code`,{children:`part / whole * 100`}),` и`,(0,_.jsx)(`code`,{children:`part * 100 / whole`}),`. В обоих случаях мы используем обычное деление и сохраняем масштаб. Не путайте их с `,(0,_.jsx)(`code`,{children:`whole / part * 100`}),`, которое меняет местами часть и целое, или с целочисленным делением `,(0,_.jsx)(`code`,{children:`//`}),`, которое в маленьких долях может отбросить дробную часть.`]}),(0,_.jsxs)(`p`,{children:[`Для половины ответ получается `,(0,_.jsx)(`code`,{children:`1 / 2 * 100 = 50.0`}),`. Для трети результат не помещается ровно в один знак: после округления мы показываем `,(0,_.jsx)(`code`,{children:`33.3`}),`. Если целое число задач равно одной и задача выполнена, часть и целое равны, поэтому доля равна единице, а процент равен `,(0,_.jsx)(`code`,{children:`100.0`}),`. Эти три случая проверяют разные края: середину, дробный остаток и полный успех. Долю больше целого наши настоящие карточки дать не должны, потому что каждая завершённая запись входит в общий список.`]}),(0,_.jsx)(c,{code:`part = 1
whole = 3
ratio = part / whole
print(round(ratio * 100, 1))
print(round(ratio, 1) * 100)`,output:`33.3
30.0`,hint:`Округляем один раз: сравните округление уже переведённого процента с округлением доли.`}),(0,_.jsx)(`p`,{children:`Здесь мы не заставляем работать Planner и не вычисляем окончательную функцию. Мы проверяем только порядок действий на числах из независимого примера. Для практики запомним связь: часть делим на целое, переводим в сто единиц и округляем результат, а исходные счётчики оставляем целыми.`})]}),(0,_.jsxs)(s,{number:`05`,title:`Пустой список обрабатываем до деления`,children:[(0,_.jsxs)(`p`,{children:[`Если задач нет, `,(0,_.jsx)(`code`,{children:`total`}),` равен нулю. Значение `,(0,_.jsx)(`code`,{children:`completed / total`}),` в этом случае вычислить нельзя. Для интерфейса Planner мы заранее выбираем договор: пустой список показывает`,(0,_.jsx)(`code`,{children:`0.0`}),` процента. Это решение программы для отсутствия задач, а не результат деления на ноль.`]}),(0,_.jsxs)(`p`,{children:[`В функции `,(0,_.jsx)(`code`,{children:`completion_percent(statistics)`}),` порядок действий защищает этот случай. Сначала читаем`,(0,_.jsx)(`code`,{children:`total`}),`. Если он равен нулю, сразу возвращаем `,(0,_.jsx)(`code`,{children:`0.0`}),`. Только иначе читаем`,(0,_.jsx)(`code`,{children:`completed`}),`, делим и округляем. Условие после вычисления не поможет: ошибка уже возникнет на строке деления.`]}),(0,_.jsx)(`p`,{children:`Представим корзину для сбора листов на столе. Если в ней нет ни одного листа, нельзя честно спросить, какую долю всех листов составляют собранные. Программа всё равно может показать заранее согласованное пустое значение, чтобы пользователь видел понятный результат. Мы не подменяем знаменатель единицей и не называем это вычисленной долей.`}),(0,_.jsxs)(`p`,{children:[`Эта защита проверяется отдельно от обычных процентов. Для пустоты мы ждём ровно `,(0,_.jsx)(`code`,{children:`0.0`}),`; для половины и трети ожидаем числовые ответы по формуле. Такое разделение позволяет отличить выбранный договор пустого списка от арифметики для положительного целого.`]}),(0,_.jsxs)(`p`,{children:[`Мы возвращаем именно `,(0,_.jsx)(`code`,{children:`0.0`}),`, чтобы пустой результат сохранял числовой вид процента. Python различает целое `,(0,_.jsx)(`code`,{children:`0`}),` и дробное `,(0,_.jsx)(`code`,{children:`0.0`}),`, хотя оба значения равны нулю при сравнении. Подпись меню добавляет знак процента позже, например к значению `,(0,_.jsx)(`code`,{children:`50.0`}),`. Функция вычисления возвращает число, а не готовую строку с символом `,(0,_.jsx)(`code`,{children:`%`}),`; так арифметика остаётся отделена от оформления сообщения.`]}),(0,_.jsx)(n,{code:`def average_score(scores):
    total = 0
    for score in scores:
        total += score
    average = total / len(scores)
    if len(scores) == 0:
        return 0.0
    return round(average, 1)`,question:`Почему функция падает на пустом списке, хотя в ней есть проверка?`,options:[`Пустой список нельзя передать параметром`,`Проверка стоит после строки, где len(scores) уже делит на ноль`,`Округление всегда требует хотя бы одно число`],correctIndex:1,explanation:`Мы должны проверить делитель до вычисления. Исправление переносит условие перед делением; для пустого списка выбранный ответ возвращается сразу.`,fix:`def average_score(scores):
    if len(scores) == 0:
        return 0.0
    total = 0
    for score in scores:
        total += score
    average = total / len(scores)
    return round(average, 1)`}),(0,_.jsxs)(`p`,{children:[`В примере проверяются средние баллы, а не статистика Planner. Нас интересует только общий порядок защиты: сначала определяем, разрешено ли деление, затем выполняем его. В собственной функции мы применим тот же порядок к `,(0,_.jsx)(`code`,{children:`total`}),`, не копируя пример целиком.`]})]}),(0,_.jsxs)(s,{number:`06`,title:`Ветка stats считает полный список и выводит сводку`,children:[(0,_.jsxs)(`p`,{children:[`Во время одного запуска функция `,(0,_.jsx)(`code`,{children:`run()`}),` владеет общим списком `,(0,_.jsx)(`code`,{children:`tasks`}),`. Ветка меню получает его после команды `,(0,_.jsx)(`code`,{children:`stats`}),`, вызывает `,(0,_.jsx)(`code`,{children:`build_statistics(tasks)`}),`, передаёт словарь в `,(0,_.jsx)(`code`,{children:`completion_percent(statistics)`}),` и показывает четыре подписи. Вычисления возвращают данные; именно ветвь меню отвечает за пользовательский текст.`]}),(0,_.jsxs)(`p`,{children:[`Важно передавать полный список. Команда `,(0,_.jsx)(`code`,{children:`search`}),` временно получает список совпадений для показа, но это выборка, не новое состояние Planner. Если у нас две задачи, а поиск нашёл одну, статистика всё равно охватывает обе. Иначе экран сказал бы, что выполнена одна из одной, хотя в Planner есть вторая карточка.`]}),(0,_.jsxs)(`p`,{children:[`Если `,(0,_.jsx)(`code`,{children:`tasks`}),` пока пуст, обе функции тоже должны отработать: сводка вернёт три нуля, а процентная функция выберет договорные `,(0,_.jsx)(`code`,{children:`0.0`}),` до деления. Поэтому команда `,(0,_.jsx)(`code`,{children:`stats`}),` может безопасно показать пустое состояние ещё до первой задачи.`]}),(0,_.jsxs)(`p`,{children:[`Схема показывает путь данных от состояния карточек до строк меню. Сначала мы читаем весь `,(0,_.jsx)(`code`,{children:`tasks`}),`, затем получаем словарь счётчиков, после чего вычисляем процент и показываем показатели. Узлы описывают разные роли, а не дополнительные хранилища или новые команды.`]}),(0,_.jsx)(m,{caption:`Как текущие задачи превращаются в строки команды stats`,orientation:`vertical`,children:(0,_.jsxs)(p,{label:`Полный список tasks передаётся в подсчёт, сводка передаётся в процент, результат показывается в меню`,orientation:`vertical`,children:[(0,_.jsx)(d,{title:`Список задач`,shape:`process`,children:(0,_.jsx)(`p`,{children:`2 задачи: 1 выполнена, 1 открыта`})}),(0,_.jsx)(f,{label:`передаём все записи`}),(0,_.jsx)(d,{title:`build_statistics(tasks)`,children:`Читает статусы и возвращает total, completed, left`}),(0,_.jsx)(f,{label:`передаём словарь`}),(0,_.jsx)(d,{title:`completion_percent(statistics)`,children:`Вычисляет процент из completed и total`}),(0,_.jsx)(f,{label:`run печатает сводку`}),(0,_.jsx)(d,{title:`Вывод команды stats`,children:`Всего: 2, Выполнено: 1, Осталось: 1, Процент выполнения: 50.0%`})]})}),(0,_.jsxs)(`p`,{children:[`По схеме можно проверить, что ветвь меню использует один список, а функции не подменяют его копией или результатом поиска. Вернувшийся словарь сохраняет целые счётчики; отдельное число процента не меняет его. Если список не изменился, повторный вызов показывает те же значения. После нового `,(0,_.jsx)(`code`,{children:`add`}),` или`,(0,_.jsx)(`code`,{children:`done`}),` следующий вызов пересчитывает текущее состояние.`]}),(0,_.jsxs)(`p`,{children:[`После занятия 19 путь команды уже подготовлен: `,(0,_.jsx)(`code`,{children:`show_menu()`}),` показывает `,(0,_.jsx)(`code`,{children:`stats`}),`, проверка разрешённых имён принимает её, а в `,(0,_.jsx)(`code`,{children:`run()`}),` есть ветвь с временным ответом. Здесь мы заменяем только тело этой ветви расчётом и выводом. Меню и список допустимых команд остаются на месте, существующая ветвь `,(0,_.jsx)(`code`,{children:`done`}),` сохраняется, а расчёт получает полный `,(0,_.jsx)(`code`,{children:`tasks`}),`. Заглушку нельзя оставить раньше реального обработчика: по вводу `,(0,_.jsx)(`code`,{children:`stats`}),` должен выполняться именно новый расчёт. Отдельный `,(0,_.jsx)(`code`,{children:`handle_stats`}),` не нужен, потому что `,(0,_.jsx)(`code`,{children:`run()`}),` уже располагает списком и отвечает за вывод.`]}),(0,_.jsxs)(`p`,{children:[`Для отдельной проверки функции не нужно возвращать наружу локальный `,(0,_.jsx)(`code`,{children:`tasks`}),` из `,(0,_.jsx)(`code`,{children:`run()`}),`. В терминале можно запустить `,(0,_.jsx)(`code`,{children:`python -i main.py`}),`: параметр `,(0,_.jsx)(`code`,{children:`-i`}),` оставляет Python в интерактивном режиме после завершения файла. Сначала мы увидим обычное меню. Команда `,(0,_.jsx)(`code`,{children:`exit`}),`завершит цикл `,(0,_.jsx)(`code`,{children:`run()`}),`, затем появится приглашение `,(0,_.jsx)(`code`,{children:`>>>`}),`. На нём доступны определения функций из файла, но локального списка `,(0,_.jsx)(`code`,{children:`tasks`}),` уже нет. Мы вызываем проверяемую функцию с коротким явно заданным аргументом, а затем сравниваем ответ. Чтобы снова пройти настоящее меню, при том же приглашении вызываем `,(0,_.jsx)(`code`,{children:`run()`}),`; его локальный список начнётся заново.`]}),(0,_.jsx)(`p`,{children:`До практики соберём полный короткий пример на другом сюжете. Три проверки на вход встречи, две из них пройдены. Цикл считает все проверки, отдельная арифметика получает долю, а вывод соединяет числа в одну строку:`}),(0,_.jsx)(g,{caption:`Независимый пример: проверки регистрации на встречу`,code:`checks = [True, False, True]
total = 0
passed = 0
for check in checks:
    total += 1
    if check:
        passed += 1
left = total - passed
percent = round(passed / total * 100, 1)
print(total, passed, left, percent)`}),(0,_.jsxs)(`p`,{children:[`Точный вывод этого кода: `,(0,_.jsx)(`code`,{children:`3 2 1 66.7`}),`.`]}),(0,_.jsxs)(`p`,{children:[`Мы отделили этот расчёт от Planner: в примере булевы отметки, нет словаря задачи, функций или команды меню. Теперь можно перенести знакомые идеи в правильные роли проекта: сводка возвращает данные, процент рассчитывается отдельно, а вывод остаётся внутри `,(0,_.jsx)(`code`,{children:`run()`}),`.`]})]}),(0,_.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,_.jsx)(r,{tone:`info`,children:`Сначала в редакторе платформы закрепим точный интерфейс двух функций на разных наборах задач. Затем перенесём их в main.py. Результат build_statistics — словарь с ключами total, completed, left; completion_percent получает один этот словарь. Кортеж и два числовых параметра не соответствуют договору, даже если команда stats печатает те же числа.`}),(0,_.jsxs)(o,{children:[`Работаем в том же локальном StudyHub и продолжаем один `,(0,_.jsx)(`code`,{children:`main.py`}),`. Команда `,(0,_.jsx)(`code`,{children:`stats`}),` уже видна и проходит проверку ввода, но её ветвь пока заглушка. Сначала добавим вычисления по отдельности, затем заменим заглушку и проверим пустой список до остальных сценариев.`]}),(0,_.jsx)(u,{variant:`connected`,items:[{title:`Рассчитаем и проверим`,description:`Мы напишем build_statistics и completion_percent, отдельно проверим пустой список, смешанный набор, треть и полный процент.`},{title:`Подключим и пройдём сценарий`,description:`Мы заменим заглушку в run, сохраним меню, допуск stats и ветвь done, затем проверим пустой tasks, поиск и новую задачу.`}]}),(0,_.jsxs)(`p`,{children:[`Каждую часть начинаем после соответствующего объяснения. Для локальных вызовов используем явно заданные небольшие списки; локальный `,(0,_.jsx)(`code`,{children:`tasks`}),` внутри `,(0,_.jsx)(`code`,{children:`run()`}),` не становится доступен снаружи. В точке A после занятия 19 команда уже видна и разрешена, но её ветвь печатает заглушку. Мы не перестраиваем этот путь: заменяем ответ заглушки расчётом и сразу проверяем пустой Planner через настоящее меню.`]}),(0,_.jsx)(`p`,{children:`В итоге один список даёт одну актуальную сводку, а предыдущие команды продолжают работать. Мы сверим пустой случай, добавление и завершение задач, результаты поиска, полный вывод списка и состояние проекта после правок.`})]})]})}export{v as Lesson19_1};